import { readFileSync, writeFileSync } from "node:fs";

export function monokaiUtilityCSS(source: string): string {
  const block = source.match(/^\.dark\s*\{([\s\S]*?)^\}/m)?.[1];
  if (!block) throw new Error("Monokai has no root .dark palette");
  const declarations = block.replace(/\/\*[\s\S]*?\*\//g, "");
  const colors = [...declarations.matchAll(/(--[\w-]+):\s*([^;]+);/g)]
    .filter(
      ([, , value]) => value?.trim().startsWith("#") || value?.trim().startsWith("color-mix("),
    )
    .map(([, name]) => name);
  return [
    "/* Generated by scripts/storybook-theme.ts from Monokai; values stay owned by the host theme. */",
    "@theme inline {",
    ...colors.map((name) => `  --color-${name?.slice(2)}: var(${name});`),
    "  --color-card-foreground: var(--foreground);",
    "  --color-popover-foreground: var(--foreground);",
    "}",
    "",
  ].join("\n");
}

if (import.meta.main) {
  const output = monokaiUtilityCSS(readFileSync("plugins/monokai/themes/bb-monokai.css", "utf8"));
  const target = "packages/ui/theme.css";
  if (process.argv.includes("--check")) {
    if (readFileSync(target, "utf8") !== output)
      throw new Error("Run bun scripts/storybook-theme.ts to refresh Monokai utilities");
  } else writeFileSync(target, output);
}
